##########################################################
# OTTIMIZZAZIONE SERVER

<IfModule mod_deflate.c>
    
    # Abilita compressione gzip
    SetOutputFilter DEFLATE

    # Da non comprimere
    SetEnvIfNoCase Request_URI \.(?:gif|jpe?g|png)$ no-gzip dont-vary
    SetEnvIfNoCase Request_URI \.(?:exe|t?gz|zip|bz2|sit|rar)$ no-gzip dont-vary

</IfModule>

<IfModule mod_headers.c>
    
    Header unset ETag
    
    # Abilita keep alive
    Header set Connection keep-alive

    # Header Utf 8
    AddDefaultCharset utf-8
    AddCharset utf-8 .htm .html .css .js .woff .woff2

    # cache per risorse compresse
    <FilesMatch "\.(js|css|xml|gz|html)$">
        Header append Vary: Accept-Encoding
    </FilesMatch>
    
    # 1 settimana (js e css in caso di modifiche vengono comunque ricompattati con nuovo nome bypassando la cache)
    <FilesMatch ".(js|css)(\?)*$">
        Header set Cache-Control "max-age=604800"
    </FilesMatch>
    
    # 1 settimana
    <FilesMatch ".(flv|gif|jpg|jpeg|png|ico|swf|pdf|txt|svg)$">
        Header set Cache-Control "max-age=604800"
    </FilesMatch>
    
    # 1 giorno
    <FilesMatch ".file_public(.*)$">
        Header set Cache-Control "max-age=86400"
    </FilesMatch>

    # 1 minuto
    <FilesMatch ".(html|htm|php)$">
        Header set Cache-Control "max-age=60"
    </FilesMatch>

</IfModule>

# il blocco seguente aumenta compatibilità con alcuni user agent (http/1.0)
# normalmente Cache-Control ha precedenza
<IfModule mod_expires.c>

    ExpiresActive on
    ExpiresDefault "access plus 1 month"

</IfModule>
