<?php
/**
 * Inizializzazione base
 */
if (!session_id()) {session_start();}
ob_start();


/**
 * Impostazioni server
 */
date_default_timezone_set("Europe/Berlin");


require __DIR__.'/../../vendor/autoload.php';


/**
 * Autoload
 */
define("AUTOLOAD_BASE_PATH", __DIR__.'/lib');
spl_autoload_register(function($className){

    // "riflette" albero dei namespace sul filesystem
    $className = ltrim($className, '\\');
    $fileName  = '';
    $namespace = '';
    if ($lastNsPos = strrpos($className, '\\')) {

        $namespace = substr($className, 0, $lastNsPos);

        $className = substr($className, $lastNsPos + 1);

        $fileName  =  AUTOLOAD_BASE_PATH.'/'.str_replace('\\', "/", $namespace) . "/";
    } else {
        $fileName  =  AUTOLOAD_BASE_PATH.'/';
    }

    $fileName .= $className . '.php';

    // include la classe
    if (file_exists($fileName)) :
        require $fileName;
    endif;

});


/**
 * Carico file env corrispondente al nome host, se c'è,
